    {
      "id": "hand_knob",
      "role": "final",
      "material": "PLA high-speed, black",
      "code": "def build(p):\n    import math\n    # Circular body with six shallow edge scallops for finger grip.\n    body = cq.Workplane('XY').circle(p.outer_d / 2).extrude(p.knob_t)\n    r = p.outer_d / 2 + p.grip_notch_offset\n    for i in range(p.grip_notch_count):\n        a = 2 * math.pi * i / p.grip_notch_count\n        cutter = (cq.Workplane('XY').center(r * math.cos(a), r * math.sin(a))\n                  .circle(p.grip_notch_r).extrude(p.knob_t + 0.2).translate((0, 0, -0.1)))\n        body = body.cut(cutter)\n    def hex_points(af):\n        cr = af / math.sqrt(3.0)\n        return [(cr * math.cos(math.radians(30 + 60 * i)),\n                 cr * math.sin(math.radians(30 + 60 * i))) for i in range(6)]\n    # Deep press-fit socket, open at the top face.\n    socket = (cq.Workplane('XY').polyline(hex_points(p.nut_socket_af)).close()\n              .extrude(p.socket_depth + 0.1)\n              .translate((0, 0, p.knob_t - p.socket_depth)))\n    body = body.cut(socket)\n    # Short, wider hex lead-in at the mouth; socket walls below remain undersized.\n    lead = (cq.Workplane('XY').polyline(hex_points(p.socket_leadin_af)).close()\n            .extrude(p.leadin_depth + 0.1)\n            .translate((0, 0, p.knob_t - p.leadin_depth)))\n    body = body.cut(lead)\n    bore = cq.Workplane('XY').circle(p.bolt_clearance_d / 2).extrude(p.knob_t + 0.2).translate((0, 0, -0.1))\n    return body.cut(bore)",
