      "material": "PLA high-speed, black",
      "code": "def build(p):\n    import math\n    block = cq.Workplane('XY').rect(p.coupon_w, p.coupon_w).extrude(p.coupon_t)\n    def hex_points(af):\n        cr = af / math.sqrt(3.0)\n        return [(cr * math.cos(math.radians(30 + 60 * i)),\n                 cr * math.sin(math.radians(30 + 60 * i))) for i in range(6)]\n    socket = (cq.Workplane('XY').polyline(hex_points(p.nut_socket_af)).close()\n              .extrude(p.socket_depth + 0.1)\n              .translate((0, 0, p.coupon_t - p.socket_depth)))\n    block = block.cut(socket)\n    lead = (cq.Workplane('XY').polyline(hex_points(p.socket_leadin_af)).close()\n            .extrude(p.leadin_depth + 0.1)\n            .translate((0, 0, p.coupon_t - p.leadin_depth)))\n    block = block.cut(lead)\n    bore = cq.Workplane('XY').circle(p.bolt_clearance_d / 2).extrude(p.coupon_t + 0.2).translate((0, 0, -0.1))\n    return block.cut(bore)",
